WITH cleaned AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, UPPER(txn_type) AS txn_type_upper FROM transactions WHERE txn_time > TO_DATE('2023-07-08')) SELECT CASE WHEN amount >= 4100 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, txn_type, AVG(amount) FILTER (WHERE merchant = 'Starbucks') AS starbucks_avg_amount, SUM(CASE WHEN merchant = 'Amazon' THEN amount ELSE 0 END) AS amazon_amount, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM cleaned GROUP BY CASE WHEN amount >= 4100 THEN 'LARGE' ELSE 'SMALL' END, txn_type ORDER BY amount_tier
